CREATE TABLE users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,must_change_password BOOLEAN NOT NULL DEFAULT FALSE,password_version INTEGER NOT NULL DEFAULT 1,credential_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at BIGINT NOT NULL,id TEXT UNIQUE NOT NULL,created_at BIGINT NOT NULL,last_seen_at BIGINT NOT NULL,idle_seconds INTEGER NOT NULL,remember BOOLEAN NOT NULL,csrf_token TEXT NOT NULL,credential_version INTEGER NOT NULL,device_name TEXT NOT NULL,transport TEXT NOT NULL DEFAULT 'cookie',created_seq BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE books(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,revision INTEGER NOT NULL,ledger JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL,authority TEXT NOT NULL DEFAULT 'snapshot');
CREATE INDEX books_user ON books(user_id);
CREATE TABLE book_members(book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL,PRIMARY KEY(book_id,user_id));
CREATE TABLE book_invites(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,code_hash TEXT UNIQUE NOT NULL,role TEXT NOT NULL,expires_at BIGINT NOT NULL,used_by TEXT,revoked_at BIGINT,created_by TEXT NOT NULL);
CREATE TABLE book_backups(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,ledger JSONB NOT NULL,revision INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE book_operations(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,user_id TEXT NOT NULL,source TEXT NOT NULL,summary TEXT NOT NULL,revision INTEGER NOT NULL,before_json JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL,created_seq BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE book_requests(book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,user_id TEXT NOT NULL,request_key TEXT NOT NULL,digest TEXT NOT NULL,result JSONB NOT NULL,PRIMARY KEY(book_id,user_id,request_key));
CREATE TABLE open_tokens(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,user_id TEXT NOT NULL,name TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,scopes JSONB NOT NULL,expires_at BIGINT NOT NULL,revoked_at BIGINT,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE open_rate_limits(token_id TEXT PRIMARY KEY REFERENCES open_tokens(id) ON DELETE CASCADE,"window" BIGINT NOT NULL,hits INTEGER NOT NULL);
CREATE TABLE open_requests(token_id TEXT NOT NULL REFERENCES open_tokens(id) ON DELETE CASCADE,request_key TEXT NOT NULL,digest TEXT NOT NULL,status INTEGER NOT NULL,result JSONB NOT NULL,created_at BIGINT NOT NULL,PRIMARY KEY(token_id,request_key));
CREATE TABLE fx_rates(currency TEXT NOT NULL,date TEXT NOT NULL,rate TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(currency,date));
CREATE TABLE attachments(id TEXT PRIMARY KEY,book_id TEXT REFERENCES books(id) ON DELETE CASCADE,user_id TEXT NOT NULL,mime TEXT NOT NULL,name TEXT NOT NULL,hash TEXT NOT NULL,bytes BYTEA NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE model_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,configuration JSONB NOT NULL,secret TEXT);
CREATE TABLE book_options(book_id TEXT PRIMARY KEY REFERENCES books(id) ON DELETE CASCADE,ai_auto_post BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE scheduler_runs(book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,occurrence TEXT NOT NULL,PRIMARY KEY(book_id,occurrence));
CREATE INDEX book_operations_time ON book_operations(book_id,revision);
CREATE TABLE auth_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,resets_at BIGINT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX book_members_user ON book_members(user_id);
CREATE INDEX attachments_owner ON attachments(user_id,book_id,hash);
